ACMsg.MPY_NEOPIXEL_NEOPIXEL_INDEX = "Index access: get/set un pixel con <b>strip[i]</b> (e.g. <b>np[0] = (255, 0, 0)</b>).";
ACMsg.MPY_NEOPIXEL_ORDER = "Constant defining il colore canale ordine (e.g. RGB/GRB) utilizzato by some NeoPixels. Restituisce: <b>int</b>.";
ACMsg.MPY_NEOPIXEL_INIT = "Crea un NeoPixel strip su <b>pin</b> con <b>n</b> LEDs. <b>bpp</b> è byte-per-pixel (predefinito <b>3</b> per RGB, <b>4</b> per RGBW). Restituisce: <b>NeoPixel</b>.";
ACMsg.MPY_NEOPIXEL_CLEAR = "Clears tutti LEDs (fills il buffer con 0). Call <b>show()</b> o <b>write()</b> a make il update visible.";
ACMsg.MPY_NEOPIXEL_SHOW = "Sends il corrente buffer a il strip e displays il colours. Call questo dopo changing pixels.";
ACMsg.MPY_NEOPIXEL_WRITE = "Equivalent a <b>show()</b> su micro:bit V2: sends il corrente buffer a il strip.";
ACMsg.MPY_NEOPIXEL_FILL = "Sets tutti LEDs a <b>colore</b> (un RGB/RGBW tuple di lunghezza <b>bpp</b>, e.g. <b>(0,0,255)</b>). Then use <b>show()</b> o <b>write()</b>.";
ACMsg.MPY_NEOPIXEL_GETITEM = "Restituisce il colore di il pixel at <b>indice</b> come un RGB/RGBW tuple. Restituisce: <b>tuple</b>.";
ACMsg.MPY_NEOPIXEL_SETITEM = "Sets il pixel at <b>indice</b> a <b>colore</b> (un RGB/RGBW tuple). Don't forget <b>show()</b> o <b>write()</b>.";
ACMsg.MPY_NEOPIXEL_LEN = "Restituisce il numero di LEDs in il strip (usable con <b>len(np)</b>). Restituisce: <b>int</b>.";
// micropython
ACMsg.MPY_MICROPYTHON_MODULE = "Micropython modulo: access e controllo MicroPython internals.";
ACMsg.MPY_MICROPYTHON_CONST = "Declare che il expression è un constant so il compiler può optimise it. Typical use: da micropython import const; CONST_X = const(123); CONST_Y = const(2 * CONST_X + 1). Constants declared questo way sono still accessible come global variables da outside il modulo they sono declared in. If un constant nome begins con '_' then it è hidden (non disponibile come un global variable) e does non take up qualsiasi memoria during execution. const() è recognised direttamente by il MicroPython parser e è provided mainly so scripts può run under entrambi CPython e MicroPython utilizzando il stesso pattern.";
ACMsg.MPY_MICROPYTHON_OPT_LEVEL = "Ottiene o imposta il optimisation level utilizzato per subsequent compilation. If level è provided, questo sets it e returns None; altrimenti it returns il livello di ottimizzazione corrente. il optimisation level controls: assertions (level 0: enabled e compiled in bytecode; level 1+: non compiled); il built-in __debug__ variable (level 0: True; level 1+: False); e source-codice riga numbers stored con bytecode (levels 0/1/2: stored so exceptions può report il riga numero; level 3+: non stored). il predefinito optimisation level è di solito 0.";
ACMsg.MPY_MICROPYTHON_MEM_INFO = "Stampa informazioni about attualmente utilizzato memoria. If il facoltativo verbose argument è fornito then extra informazioni è printed. il exact output è porta/implementation dependent but in genere includes il amount di stack e heap utilizzato; in verbose modalità it può print il entire heap showing che blocks sono utilizzato e che sono free.";
ACMsg.MPY_MICROPYTHON_QSTR_INFO = "Stampa informazioni about attualmente interned strings (qstrs). If il facoltativo verbose argument è fornito then extra informazioni è printed. il exact output è porta/implementation dependent but in genere includes il numero di interned strings e il amount di RAM they use; in verbose modalità it prints il nomi di tutti RAM-interned strings.";
ACMsg.MPY_MICROPYTHON_STACK_USE = "Restituisce un intero representing il corrente amount di stack che è being utilizzato. il absolute valore è di solito non very useful; it è intended a compute differences in stack usage at different points.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCK = "Lock il heap. When locked, no memoria allocation può occur e un MemoryError will essere raised se qualsiasi heap allocation è attempted. heap_lock() può essere nested (called multipli times) che increases un internal lock depth; heap_unlock() deve essere called il stesso numero di times a make il heap disponibile di nuovo. If il REPL becomes active con il heap locked then it will essere forcefully unlocked.";
ACMsg.MPY_MICROPYTHON_HEAP_UNLOCK = "Unlock il heap (nestable). Restituisce il corrente lock depth dopo unlocking; 0 means il heap è non locked.";
ACMsg.MPY_MICROPYTHON_HEAP_LOCKED = "Restituisce il corrente heap lock depth come un non-negative intero (0 means il heap è non locked). Note: heap_locked() è non enabled su più ports per impostazione predefinita e può require un build option.";
ACMsg.MPY_MICROPYTHON_KBD_INTR = "Imposta il character codice che will genera un KeyboardInterrupt exception. By predefinito questo è 3 during script execution, corresponding a Ctrl-C. Passing -1 disables capture di Ctrl-C; passing 3 restores it. questo può essere utilizzato a prevent capturing Ctrl-C su il incoming flusso di characters che è di solito utilizzato per il REPL, se che flusso è utilizzato per altro purposes.";
ACMsg.MPY_MICROPYTHON_SCHEDULE = "Schedule il funzione func a essere executed \"very soon\". il funzione receives arg come its singolo argument. \"Very soon\" means MicroPython will try a execute it at il earliest possible time mentre remaining efficient, e subject a questi conditions: un scheduled funzione never preempts another scheduled funzione; scheduled funzioni run tra bytecode opcodes, so fundamental Python operations (like appending a un elenco) sono atomic; e un porta può define critical regions dove scheduled funzioni will non run (they può essere scheduled there but will solo execute once il region è exited—un example è un preempting IRQ). un common use è a schedule un callback da un preempting IRQ: questo avoids IRQ restrictions (such come il heap being locked) by deferring work. su multi-threaded ports, behavior dipende da il Global Interpreter Lock (GIL): con GIL enabled, il scheduled funzione può preempt qualsiasi thread e run in its context; con GIL disabled, it solo preempts il main thread. Note: se schedule() è called da un preempting IRQ dove allocation è non allowed, e il callback passed è un bound method, passing it direttamente può fail because creating un bound-method reference allocates; un typical workaround è a create e store il method reference in il class constructor e schedule che stored reference. There è un finito queue per scheduled callbacks e schedule() raises RuntimeError se il queue è full.";
ACMsg.MPY_MICROPYTHON_RINGIO = "RingIO provides un fixed-dimensione ring buffer per byte con un flusso interface, comparable a un FIFO-like variant di io.BytesIO. You può construct it con un intero dimensione (it will allocate un suitable internal buffer) o pass un existing buffer-protocol oggetto such come un bytearray a use it sul posto. il classic ring buffer algorithm è utilizzato e one byte è reserved per tracking: quando initialised con un intero dimensione questo overhead è accounted per (e.g. RingIO(16) allocates 17 byte internally so it può hold 16 byte), but quando you pass un pre-allocated buffer, one byte meno di its original lunghezza è disponibile per storage (e.g. RingIO(bytearray(16)) holds 15 byte). un RingIO instance può essere IRQ/thread safe quando utilizzato a pass dati in un singolo direction (per example, written in un IRQ e read in non-IRQ codice, o il reverse). questo does non hold se you write a il stesso instance da entrambi IRQ e non-IRQ contexts, che può cause dati corruption.";
ACMsg.MPY_MICROPYTHON_RINGIO_ANY = "Restituisce un intero counting il numero di byte che può essere read. Restituisce: int.";
ACMsg.MPY_MICROPYTHON_RINGIO_READ = "Read available bytes (non-blocking). If nbytes is specified then read at most that many bytes, otherwise read as much as possible. Returns: a bytes object (empty bytes if no data is available)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_READLINE = "Legge un riga ending in un newline character (\n) o return se one exists in il buffer; altrimenti return disponibile byte in il buffer. If nbytes è specified then read at più che many byte. Restituisce: byte.";
ACMsg.MPY_MICROPYTHON_RINGIO_READINTO = "Read available bytes into buf. If nbytes is specified then read at most that many bytes, otherwise read at most len(buf) bytes. Returns: int (number of bytes read into buf)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_WRITE = "Non-blocking write of bytes from buf into the ring buffer, limited by the available space in the ring buffer. Returns: int (number of bytes written)." ;
ACMsg.MPY_MICROPYTHON_RINGIO_CLOSE = "No-op provided as part of the standard stream interface; has no effect on the data in the ring buffer." ;
ACMsg.MPY_MICROPYTHON_NATIVE_DECORATOR = "Compile il decorated funzione a native codice macchina instead di bytecode. Often faster, but uses più memoria e has limitations (e.g. some Python features sono restricted). Availability dipende da il porta/firmware.";
ACMsg.MPY_MICROPYTHON_VIPER_DECORATOR = "Compile utilizzando il Viper emitter per higher performance, especially per intero/bit operations. Uses special Viper-native tipi e è meno Python-compliant. Availability dipende da il porta/firmware.";
ACMsg.MPY_MICROPYTHON_ASM_THUMB_DECORATOR = "Define un inline assembler funzione per ARM Thumb/Thumb-2 targets. il funzione body uses MicroPython's assembler DSL. solo disponibile su supportato ARM builds.";
ACMsg.MPY_MICROPYTHON_ASM_XTENSA_DECORATOR = "Define un inline assembler funzione per Xtensa targets (e.g. some ESP8266/ESP32 builds). solo disponibile quando il firmware enables il Xtensa inline assembler.";
ACMsg.MPY_MICROPYTHON_ASM_RV32_DECORATOR ="Define un inline assembler funzione per 32-bit RISC-V targets (RV32) quando enabled by il porta/firmware (e.g. some rp2 configurations in RISC-V modalità).";

// bluetooth
ACMsg.MPY_BLUETOOTH_BLE = "Low-level BLE interface. <b>bluetooth.BLE()</b> returns il singleton driver oggetto. Restituisce: <b>BLE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_ACTIVE = "Attiva/disable il BLE radio (facoltativo arg) e return stato corrente. il radio deve essere active prima utilizzando altro BLE methods. Restituisce: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_CONFIG = "Ottiene/imposta BLE configuration. Query con <b>config('param')</b>, set con keywords <b>config(param=valore,...)</b>. Supported params include <b>'mac'</b>, <b>'addr_modalità'</b>, <b>'gap_nome'</b>, <b>'rxbuf'</b>, <b>'mtu'</b>, <b>'bond'</b>, <b>'mitm'</b>, <b>'io'</b>, <b>'le_secure'</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_ADVERTISE = "Avvia advertising con interval in microsecondi (rounded down a nearest 625µs). Arresta advertising con <b>interval_us=None</b>. <b>adv_dati</b>/<b>resp_dati</b> deve support buffer protocol; passing <b>None</b> reuses previous payload; use <b>b''</b> a clear.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_CONNECT = "Connette a un peripheral by address (use addr_tipo da scan). Cancel un outstanding attempt con <b>gap_connect(None)</b>. Success raises <b>_IRQ_PERIPHERAL_CONNECT</b>; cancel/disconnect raises <b>_IRQ_PERIPHERAL_DISCONNECT</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_DISCONNECT = "Disconnette un connesso peer (central o peripheral, un seconda di role). Genera <b>_IRQ_PERIPHERAL_DISCONNECT</b> o <b>_IRQ_CENTRAL_DISCONNECT</b>. Restituisce <b>True</b> se handle era connesso, else <b>False</b>. Restituisce: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PAIR = "Initiate pairing con remote dispositivo. Ensure <b>io</b>, <b>mitm</b>, <b>le_secure</b>, <b>bond</b> sono configured primo. su success emits <b>_IRQ_ENCRYPTION_UPDATE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_PASSKEY = "Respond a un <b>_IRQ_PASSKEY_ACTION</b> evento (passkey I/O). Action determines whether a input, display, o confirm numeric comparison.";
ACMsg.MPY_BLUETOOTH_BLE_GAP_SCAN = "Scansiona per <b>durata_ms</b> (0 = indefinitely, None = stop). Configura ciclo di lavoro con <b>interval_us</b>/<b>window_us</b>. Emits <b>_IRQ_SCAN_RESULT</b> con (<b>addr_tipo</b>, <b>addr</b>, <b>adv_tipo</b>, <b>rssi</b>, <b>adv_dati</b>) e <b>_IRQ_SCAN_DONE</b> quando finished.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_CHARACTERISTICS = "Discover characteristics in handle intervallo (facoltativo <b>uuid</b> filter). Emits <b>_IRQ_GATTC_CHARACTERISTIC_RESULT</b> e then <b>_IRQ_GATTC_CHARACTERISTIC_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_DESCRIPTORS = "Discover descriptors in handle intervallo. Emits <b>_IRQ_GATTC_DESCRIPTOR_RESULT</b> e then <b>_IRQ_GATTC_DESCRIPTOR_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_DISCOVER_SERVICES = "Discover services su un connesso server (facoltativo <b>uuid</b> filter). Emits <b>_IRQ_GATTC_SERVICE_RESULT</b> e then <b>_IRQ_GATTC_SERVICE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_EXCHANGE_MTU = "Initiate ATT MTU exchange utilizzando preferred MTU set by <b>config(mtu=valore)</b>. Emits <b>_IRQ_MTU_EXCHANGED</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_READ = "Issue un remote read. Emits <b>_IRQ_GATTC_READ_RESULT</b> e then <b>_IRQ_GATTC_READ_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTC_WRITE = "Issue un remote write. <b>modalità=0</b> write-senza-response (no evento). <b>modalità=1</b> write-con-response; su response emits <b>_IRQ_GATTC_WRITE_DONE</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_INDICATE = "Invia un indication a un connesso client. If <b>dati</b> è None, send corrente local valore; altrimenti send provided <b>dati</b>. su ack/failure raises <b>_IRQ_GATTS_INDICATE_DONE</b>. Sent regardless di subscription status.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_NOTIFY = "Invia un notification a un connesso client. If <b>dati</b> è None, send corrente local valore; altrimenti send provided <b>dati</b>. Sent regardless di subscription status.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_READ = "Legge local valore per un handle (written by <b>gatts_write</b> o un remote client). Restituisce: <b>byte</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_REGISTER_SERVICES = "Registra GATT server services/characteristics, replacing qualsiasi existing. Restituisce un elenco di tuples di valore handles (flattened). Note: advertising deve essere stopped prima registering. Restituisce: <b>elenco</b>.";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_SET_BUFFER = "Imposta internal buffer dimensione per un valore (predefinito 20). If <b>append=True</b>, remote writes append instead di replace. When utilizzando <b>gatts_read</b>, il valore è cleared dopo reading (useful per UART-like services).";
ACMsg.MPY_BLUETOOTH_BLE_GATTS_WRITE = "Scrive local valore per un handle. If <b>send_update=True</b>, subscribed clients sono notified/indicated un seconda di characteristic properties.";
ACMsg.MPY_BLUETOOTH_BLE_IRQ = "Registra un IRQ callback per BLE eventi. Handler signature: <b>gestore(evento, dati)</b>. Some fields in <b>dati</b> sono temporary <b>memoryview</b> objects valid solo during il callback; copia con <b>byte()</b> o <b>bluetooth.UUID()</b> se needed.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_CONNECT = "Connette a un listening peer su <b>psm</b> con local MTU <b>mtu</b>. su success emits <b>_IRQ_L2CAP_CONNECT</b>, su failure emits <b>_IRQ_L2CAP_DISCONNECT</b> con non-zero status.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_DISCONNECT = "Disconnette un active L2CAP canale identified by (<b>conn_handle</b>, <b>cid</b>).";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_LISTEN = "Listen per incoming L2CAP CoC su <b>psm</b> con local MTU <b>mtu</b>. Emits <b>_IRQ_L2CAP_ACCEPT</b> (return non-zero a reject) e <b>_IRQ_L2CAP_CONNECT</b> once accepted. Note: cannot stop listening.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_RECVINTO = "Riceve L2CAP dati in <b>buf</b>. Restituisce numero di byte read; se <b>buf</b> è None, returns numero di byte disponibile. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_BLE_L2CAP_SEND = "Invia buffer su un L2CAP canale. Restituisce <b>False</b> se canale è stalled; wait per <b>_IRQ_L2CAP_SEND_READY</b> prima sending di nuovo. Restituisce: <b>bool</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_AUTHENTICATED_SIGNED_WRITE = "GATT flag constant <b>_FLAG_AUTHENTICATED_SIGNED_WRITE</b> (bitmask per characteristics/descriptors). GATT flag: authenticated signed write. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_AUX_WRITE = "GATT flag constant <b>_FLAG_AUX_WRITE</b> (bitmask per characteristics/descriptors). GATT flag: auxiliary write. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_BROADCAST = "GATT flag constant <b>_FLAG_BROADCAST</b> (bitmask per characteristics/descriptors). GATT flag: broadcast. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_INDICATE = "GATT flag constant <b>_FLAG_INDICATE</b> (bitmask per characteristics/descriptors). GATT flag: indicate. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_NOTIFY = "GATT flag constant <b>_FLAG_NOTIFY</b> (bitmask per characteristics/descriptors). GATT flag: notify. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ = "GATT flag constant <b>_FLAG_READ</b> (bitmask per characteristics/descriptors). GATT flag: read permitted. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_AUTHENTICATED = "GATT flag constant <b>_FLAG_READ_AUTHENTICATED</b> (bitmask per characteristics/descriptors). GATT flag: authenticated read required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_AUTHORIZED = "GATT flag constant <b>_FLAG_READ_AUTHORIZED</b> (bitmask per characteristics/descriptors). GATT flag: authorized read required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_READ_ENCRYPTED = "GATT flag constant <b>_FLAG_READ_ENCRYPTED</b> (bitmask per characteristics/descriptors). GATT flag: encrypted read required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE = "GATT flag constant <b>_FLAG_WRITE</b> (bitmask per characteristics/descriptors). GATT flag: write con response. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_AUTHENTICATED = "GATT flag constant <b>_FLAG_WRITE_AUTHENTICATED</b> (bitmask per characteristics/descriptors). GATT flag: authenticated write required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_AUTHORIZED = "GATT flag constant <b>_FLAG_WRITE_AUTHORIZED</b> (bitmask per characteristics/descriptors). GATT flag: authorized write required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_ENCRYPTED = "GATT flag constant <b>_FLAG_WRITE_ENCRYPTED</b> (bitmask per characteristics/descriptors). GATT flag: encrypted write required. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_FLAG_WRITE_NO_RESPONSE = "GATT flag constant <b>_FLAG_WRITE_NO_RESPONSE</b> (bitmask per characteristics/descriptors). GATT flag: write senza response. Restituisce: <b>int</b>.";
ACMsg.MPY_BLUETOOTH_GATTS_ERROR_INSUFFICIENT_AUTHENTICATION = "GATTS read-request return codice <b>_GATTS_ERROR_INSUFFICIENT_AUTHENTICATION</b>. Insufficient authentication. Restituisce: <b>int</b>.";
